import { useEffect, useState } from 'react';
import { searchData } from '../services/tsApi';
import { THOUGHTSPOT_MODEL_ID } from '../config/thoughtspot';

export interface KpiValues {
  flightSpend: string;
  totalTrips: string;
  onPolicy: string;
  avgTripCost: string;
  carbonEmissions: string;
  activeTravellers: string;
  loading: boolean;
  error: boolean;
}

// Fallback figures shown immediately — update with real values or matching query strings
const FALLBACK: KpiValues = {
  flightSpend: '$1.7M',
  totalTrips: '529',
  onPolicy: '82%',
  avgTripCost: '$3,214',
  carbonEmissions: '567 KG',
  activeTravellers: '148',
  loading: false,
  error: false,
};

// Adjust these query strings to match your model's column names
const QUERIES: Record<keyof Omit<KpiValues, 'loading' | 'error'>, string> = {
  flightSpend: '[total spend]',
  totalTrips: '[number of trips]',
  onPolicy: '[on policy] %',
  avgTripCost: '[average trip cost]',
  carbonEmissions: '[total carbon emissions]',
  activeTravellers: '[unique travellers]',
};

function formatNumber(val: any, isCurrency = false, isPercent = false): string {
  const n = parseFloat(String(val));
  if (isNaN(n)) return '';
  if (isPercent) return `${Math.round(n)}%`;
  if (isCurrency) {
    if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(1)}M`;
    if (n >= 1_000) return `$${Math.round(n / 1000).toLocaleString()}K`;
    return `$${Math.round(n).toLocaleString()}`;
  }
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${Math.round(n / 1000).toLocaleString()}K`;
  return Math.round(n).toLocaleString();
}

async function fetchOne(query: string): Promise<any> {
  const result = await searchData(THOUGHTSPOT_MODEL_ID, query);
  return result.rows?.[0]?.[0] ?? null;
}

export function useKpiData(): KpiValues {
  // Start with fallback values so cards always show something
  const [values, setValues] = useState<KpiValues>(FALLBACK);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const keys = Object.keys(QUERIES) as Array<keyof typeof QUERIES>;
        const results = await Promise.allSettled(
          keys.map(k => fetchOne(QUERIES[k]))
        );

        if (cancelled) return;

        const updates: Partial<KpiValues> = {};
        keys.forEach((key, i) => {
          const r = results[i];
          if (r.status === 'fulfilled' && r.value != null) {
            const raw = r.value;
            if (key === 'flightSpend' || key === 'avgTripCost') {
              const formatted = formatNumber(raw, true);
              if (formatted) updates[key] = formatted;
            } else if (key === 'onPolicy') {
              const formatted = formatNumber(raw, false, true);
              if (formatted) updates[key] = formatted;
            } else if (key === 'carbonEmissions') {
              const formatted = formatNumber(raw);
              if (formatted) updates[key] = `${formatted} KG`;
            } else {
              const formatted = formatNumber(raw);
              if (formatted) updates[key] = formatted;
            }
          }
        });

        setValues(v => ({ ...v, ...updates }));
      } catch {
        // Keep fallback values on any error
      }
    })();

    return () => { cancelled = true; };
  }, []);

  return values;
}
